return {npc01001={id="npc01001",dsc="他佛法精深，武功也是极高，自淡出江湖后在寺中已修禅二十余年。",sex="男",age=56,looks=20,showequip={},withCorpse=0},npc01002={id="npc01002",dsc="海鲸帮快刀堂堂主，生性鲁莽，好吃酒肉，与丐帮帮主江上游交情颇深。",sex="男",age=30,looks=20,showequip={"长刀"},withCorpse=0},npc01003={id="npc01003",dsc="伏龙山堂主之一，他“铁陨沉砂掌”的功夫不在任天南之下，曾因争夺帮主一位跟任天南结下宿怨。",sex="男",age=42,looks=15,showequip={},withCorpse=0},npc01004={id="npc01004",dsc="信空大师的大弟子，平日主要负责协助信空大师管理寺中大小事务。他处事沉稳，深受信空大师信任，相传，信空大师有意将住持之位传于他。",sex="男",age=37,looks=18,showequip={},withCorpse=0},npc01005={id="npc01005",dsc="信空大师的二弟子，平日主要负责监察寺中弟子言行，犯错弟子必受其处罚。他为人严谨，不喜谈笑，待真参如同亲弟弟。",sex="男",age=35,looks=20,showequip={},withCorpse=0},npc01006={id="npc01006",dsc="信空大师的三弟子，年纪轻轻，武艺便已尽得信空大师真传，平日主要负责传授寺中弟子武功。他心无城府，与二师兄真荣情同手足。",sex="男",age=18,looks=18,showequip={},withCorpse=0},npc01007={id="npc01007",dsc="负责看守山门的僧侣，看上去稚气未脱。",sex="男",age=18,looks=23,showequip={},withCorpse=0},npc01008={id="npc01008",dsc="他一身黑衣黑帽，将浑身裹得严严实实，唯一露出的只有一双眼睛。他的眼中满是杀气，令人生畏。",sex="男",age=35,looks=0,showequip={},withCorpse=0},npc01009={id="npc01009",dsc="身着灰色纳衣的僧人，现在正在案台上抄写着佛经。",sex="男",age=28,looks=20,showequip={},withCorpse=0},npc01010={id="npc01010",dsc="身着灰色纳衣的僧人，现在正在打坐。",sex="男",age=27,looks=20,showequip={},withCorpse=0},npc01011={id="npc01011",dsc="一个尚未受戒的小沙弥，此刻正担着两桶水，满头大汗。",sex="男",age=15,looks=20,showequip={},withCorpse=0},npc01012={id="npc01012",dsc="身穿黄色纳衣的僧人，平日负责指引香客，对前殿的各种事务都很是了解。",sex="男",age=26,looks=17,showequip={},withCorpse=0},npc01013={id="npc01013",dsc="负责每日清晨在钟楼敲响钟鼓的僧人。",sex="男",age=35,looks=17,showequip={},withCorpse=0},npc01014={id="npc01014",dsc="负责每日傍晚在鼓楼敲响钟鼓的僧人。",sex="男",age=28,looks=17,showequip={},withCorpse=0},npc01015={id="npc01015",dsc="身着玄色纳衣的僧人，似乎在找什么东西。",sex="男",age=25,looks=19,showequip={},withCorpse=0},npc01016={id="npc01016",dsc="身着玄色纳衣的僧人，现在正坐在蒲团上做着功课。",sex="男",age=25,looks=19,showequip={},withCorpse=0},npc01017={id="npc01017",dsc="一个尚未受戒的小和尚，此刻正啃着一个馒头，眉头微皱，看来馒头不太合他的口味。",sex="男",age=15,looks=20,showequip={},withCorpse=0},npc01018={id="npc01018",dsc="一个尚未受戒的小沙弥，此刻正擦拭着殿中的器物。",sex="男",age=15,looks=20,showequip={},withCorpse=0},npc01019={id="npc01019",dsc="此人是天龙寺中的护院僧人，身材魁梧，一眼就能看出是练武的高手。",sex="男",age=40,looks=20,showequip={},withCorpse=0},npc01020={id="npc01020",dsc="此人是天龙寺中的武僧，身材魁梧，一眼就能看出是练武的高手。",sex="男",age=40,looks=20,showequip={},withCorpse=0},npc01021={id="npc01021",dsc="一个尚未受戒的小沙弥，正在打扫寺中的落叶。",sex="男",age=15,looks=20,showequip={},withCorpse=0},npc01022={id="npc01022",dsc="一个尚未受戒的小沙弥，正在案台上抄写着佛经。",sex="男",age=15,looks=20,showequip={},withCorpse=0},npc01023={id="npc01023",dsc="负责每日清晨在钟楼敲响钟鼓的僧人，看起来要比先前的敲钟僧人要年轻些。",sex="男",age=25,looks=17,showequip={},withCorpse=0}}0